--
-- Table structure for table `ruta`
--

DROP TABLE IF EXISTS `ruta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ruta` (
  `id_ruta` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci,
  `tipo` enum('micro','minibus','teleferico','otros') CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
  `color_hex` char(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci DEFAULT '#0066CC',
  `activo` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `id_grupo_umap` varchar(150) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `sentido` enum('IDA','VUELTA','NORMAL') COLLATE utf8mb4_spanish_ci DEFAULT 'NORMAL',
  `id_umap` varchar(120) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `datalayer_id` varchar(40) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `coords_geojson` longtext COLLATE utf8mb4_spanish_ci COMMENT 'GeoJSON LineString serializado',
  `uuid_capa` varchar(100) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  PRIMARY KEY (`id_ruta`),
  KEY `idx_ruta_grupo` (`id_grupo_umap`),
  KEY `idx_ruta_sentido` (`sentido`),
  CONSTRAINT `ruta_chk_1` CHECK (regexp_like(`color_hex`,_utf8mb4'^#[0-9A-Fa-f]{6}$'))
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci COMMENT='Almacena las rutas de transporte público';
/*!40101 SET character_set_client = @saved_cs_client */;

