DROP TABLE IF EXISTS `sincronizacion_google`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sincronizacion_google` (
  `id_sincronizacion` int NOT NULL AUTO_INCREMENT,
  `fecha_sincronizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `archivo_kml_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `estado` enum('PENDIENTE','PROCESANDO','COMPLETADO','ERROR') CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci DEFAULT 'PENDIENTE',
  `rutas_agregadas` int DEFAULT '0',
  `rutas_actualizadas` int DEFAULT '0',
  `paradas_agregadas` int DEFAULT '0',
  `paradas_actualizadas` int DEFAULT '0',
  `mensaje_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci,
  `usuario_ejecuto` int DEFAULT NULL,
  PRIMARY KEY (`id_sincronizacion`),
  KEY `fk_sg_usuario` (`usuario_ejecuto`),
  CONSTRAINT `fk_sg_usuario` FOREIGN KEY (`usuario_ejecuto`) REFERENCES `usuario` (`id_usuario`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci COMMENT='Registro de sincronizaciones con Google My Maps';
/*!40101 SET character_set_client = @saved_cs_client */;

